/bin/zsh -lc "cat > tb.sv <<'EOF'
module tb;
  reg clk = 0;
  reg rst_n = 0;
  reg a = 0;
  wire match;

  TopModule dut(.clk(clk), .rst_n(rst_n), .a(a), .match(match));

  always #5 clk = ~clk;

  task send_bit(input bit b);
    begin
      a = b;
      @(posedge clk);
      #1;
      "'$display("t=%0t a=%0b a_tem=%b match=%0b", $time, a, dut.a_tem, match);
    end
  endtask

  initial begin
    repeat (2) @(posedge clk);
    rst_n = 1;

    // pattern: 011000110 should match
    send_bit(0);
    send_bit(1);
    send_bit(1);
    send_bit(0);
    send_bit(0);
    send_bit(0);
    send_bit(1);
    send_bit(1);
    send_bit(0);

    // one extra bit to see late-match bugs
    send_bit(1);

    $finish;
  end
endmodule
EOF

